/// Функции, объявленные в предмете, по разбору Rust.
///
/// Разбор, а не текстовый поиск: комментарий и строковый литерал дают ложное
/// совпадение, а шаблон поиска промахивается мимо форм видимости — при первом
/// счёте `pub(super)` стоил восьми функций из семидесяти семи.
fn declared_functions() -> Vec<(&'static str, String)> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let mut declared = Vec::new();

    for file in FILES {
        let path = root.join(file);
        let text = std::fs::read_to_string(&path)
            .unwrap_or_else(|err| panic!("{} не прочитан: {err}", path.display()));
        let parsed = syn::parse_file(&text)
            .unwrap_or_else(|err| panic!("{} не разобран: {err}", path.display()));

        for item in parsed.items {
            if let syn::Item::Fn(function) = item {
                declared.push((*file, function.sig.ident.to_string()));
            }
        }
    }

    declared
}

/// Ключ строки — файл и имя вместе.
///
/// Одного имени мало: `at_then` объявлен дважды, в `grammar.rs` и в
/// `statements.rs`. По имени две строки схлопнулись бы в одну, и одна из
/// функций осталась бы без вердикта незаметно.
fn key(file: &str, name: &str) -> String {
    format!("{file}:{name}")
}

/// Состав чек-листа совпадает с составом предмета.
#[test]
fn every_grammar_function_has_a_row() {
    let declared = declared_functions();
    let declared_keys: Vec<String> = declared.iter().map(|(file, name)| key(file, name)).collect();
    let listed: Vec<String> = CHECKLIST.iter().map(|entry| key(entry.file, entry.name)).collect();

    let mut breaches = Vec::new();

    for candidate in &declared_keys {
        if !listed.contains(candidate) {
            breaches.push(format!("функция без вердикта: {candidate}"));
        }
    }

    for candidate in &listed {
        if !declared_keys.contains(candidate) {
            breaches.push(format!("вердикт без функции: {candidate}"));
        }
    }

    let mut seen = Vec::new();
    for candidate in &listed {
        if seen.contains(candidate) {
            breaches.push(format!("вердикт задан дважды: {candidate}"));
        }
        seen.push(candidate.clone());
    }

    assert!(
        !declared_keys.is_empty(),
        "разбор не нашёл ни одной функции — проверка была бы зелена вхолостую"
    );
    assert!(breaches.is_empty(), "чек-лист разошёлся с предметом:\n  {}", breaches.join("\n  "));
}

/// Ни одного неразрешённого D не осталось.
///
/// D — находка, а не исход: каждый разрешается в R, в A либо в правку,
/// снимающую форму. Пока в таблице стоит хоть один, слайс не закрыт.
#[test]
fn no_unresolved_verdict_remains() {
    let unresolved: Vec<String> = CHECKLIST
        .iter()
        .filter_map(|entry| match entry.verdict {
            Verdict::D { what } => Some(format!("{}: {what}", key(entry.file, entry.name))),
            _ => None,
        })
        .collect();

    assert!(
        unresolved.is_empty(),
        "неразрешённых вердиктов D: {}\n  {}",
        unresolved.len(),
        unresolved.join("\n  ")
    );
}

/// Обоснование есть, и вердикт R называет раздел источника.
///
/// Без этой проверки поля обоснования никто не читает: строка с верным ключом,
/// верной буквой вердикта и пустой цитатой прошла бы наравне с обоснованной.
/// Граница проверки названа прямо — машина видит, что раздел НАЗВАН, но не то,
/// что он говорит именно это. Существо обоснования остаётся предметом ревью,
/// и тест его не заменяет.
#[test]
fn every_verdict_carries_its_justification() {
    let mut breaches = Vec::new();

    for entry in CHECKLIST {
        let site = key(entry.file, entry.name);

        let justification = match entry.verdict {
            Verdict::R { section } => {
                if !names_a_section(section) {
                    breaches.push(format!("{site}: вердикт R не называет раздела Главы 4"));
                }
                section
            }
            Verdict::A { reason } => reason,
            Verdict::D { what } => what,
        };

        if justification.trim().is_empty() {
            breaches.push(format!("{site}: обоснование пусто"));
        }
    }

    assert!(!CHECKLIST.is_empty(), "чек-лист пуст — проверка была бы зелена вхолостую");
    assert!(breaches.is_empty(), "обоснования не по форме:\n  {}", breaches.join("\n  "));
}

/// Отметки, которыми обозначают невыполненную работу.
///
/// Перечень заведомо неполон и полным быть не может: способов написать «допишу
/// позже» столько же, сколько слов. Он ловит расхожие отметки, и не более того —
/// поэтому проверка ниже названа backstop, а не доказательством.
const PLACEHOLDER_MARKS: &[&str] =
    &["tbd", "todo", "fixme", "xxx", "wip", "заглушка", "потом", "позже"];

/// Нижняя граница длины обоснования.
///
/// Взята из данных, а не с потолка: самое короткое настоящее обоснование в
/// таблице — 40 знаков, а заглушки однословны. Порог ниже наблюдаемого минимума,
/// чтобы не отвергать короткое, но настоящее.
const SHORTEST_JUSTIFICATION: usize = 32;

/// Обоснование не выглядит заглушкой.
///
/// Это backstop, а не доказательство содержательности: машина отличает `TODO` от
/// фразы, но не отличает верную причину от правдоподобной. Существо обоснования
/// проверяется ревью, и граница названа здесь прямо, чтобы гейт не читался как
/// то, чем он не является.
#[test]
fn no_justification_is_a_placeholder() {
    let mut breaches = Vec::new();

    for entry in CHECKLIST {
        let site = key(entry.file, entry.name);
        let justification = match entry.verdict {
            Verdict::R { section } => section,
            Verdict::A { reason } => reason,
            Verdict::D { what } => what,
        };

        if justification.chars().count() < SHORTEST_JUSTIFICATION {
            breaches.push(format!(
                "{site}: обоснование короче {SHORTEST_JUSTIFICATION} знаков и на причину не похоже"
            ));
        }

        // Сравнение по словам, а не по подстроке: «потом» живёт внутри «потому»,
        // и подстрочный поиск краснел на трёх настоящих обоснованиях.
        let folded = justification.to_lowercase();
        for word in folded.split(|c: char| !c.is_alphanumeric()) {
            if PLACEHOLDER_MARKS.contains(&word) {
                breaches
                    .push(format!("{site}: обоснование содержит отметку незаконченного — {word}"));
            }
        }
    }

    assert!(breaches.is_empty(), "обоснования-заглушки:\n  {}", breaches.join("\n  "));
}

/// Встречается ли в тексте номер раздела Главы 4 — `4.` и цифра за точкой.
fn names_a_section(text: &str) -> bool {
    let bytes = text.as_bytes();
    bytes
        .windows(3)
        .any(|window| window[0] == b'4' && window[1] == b'.' && window[2].is_ascii_digit())
}

/// Аттестация перечисляет тот же вердикт, что и чек-лист.
///
/// Копия в прозе рядом с гейтованным оригиналом расходится с ним молча — если
/// расхождение ничем не ловится. Здесь ловится: перечень в документе обязан
/// содержать строку каждой функции с той же буквой вердикта, и лишних строк в
/// нём быть не должно.
#[test]
fn the_document_lists_every_verdict() {
    let attestation =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../docs/legal/bsl-clean-room-slice-b3.md");
    let text = std::fs::read_to_string(&attestation)
        .unwrap_or_else(|err| panic!("{} не прочитан: {err}", attestation.display()));

    let mut breaches = Vec::new();
    let mut expected = Vec::new();

    for entry in CHECKLIST {
        let letter = match entry.verdict {
            Verdict::R { .. } => 'R',
            Verdict::A { .. } => 'A',
            Verdict::D { .. } => 'D',
        };
        let row = format!("| `{}` | {letter} |", key(entry.file, entry.name));
        if !text.contains(&row) {
            breaches.push(format!("в аттестации нет строки: {row}"));
        }
        expected.push(row);
    }

    for line in text.lines() {
        let line = line.trim();
        if line.starts_with("| `src/") && !expected.iter().any(|row| row == line) {
            breaches.push(format!("в аттестации лишняя строка: {line}"));
        }
    }

    assert!(breaches.is_empty(), "перечень разошёлся с чек-листом:\n  {}", breaches.join("\n  "));
}

#[test]
fn the_document_preserves_every_referenced_finding() {
    let attestation =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../docs/legal/bsl-clean-room-slice-b3.md");
    let text = std::fs::read_to_string(&attestation)
        .unwrap_or_else(|err| panic!("{} не прочитан: {err}", attestation.display()));

    for number in 1..=10 {
        let heading = format!("### D{number} —");
        assert!(text.contains(&heading), "в аттестации нет содержательной находки D{number}");
    }
}
